<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { Brain, Plus, Sparkles, Trash2, Pin, Clock3 } from '@lucide/vue'
import { api, post, put, patch, remove, requestId } from '../lib/api'
import { choice, confirmAction, date, field, notify, openForm, run } from '../lib/ui'
import { useResource } from '../lib/resource'
import PageHeading from '../components/PageHeading.vue'
import ResourceState from '../components/ResourceState.vue'
import EmptyState from '../components/EmptyState.vue'
interface Config { enabled:boolean; auto_extract:boolean; half_life_days:number; max_recall:number; relevance_threshold:number; daily_auto_limit:number }
interface Memory { id:string; content:string; importance:number; source:string; memory_type:string; semantic_key:string; status:string; freshness:number; recall_count:number; created_at:number; expires_at?:number }
interface Score { id:string; content:string; relevance:number; freshness:number; selected:boolean; reason:string }
interface Data { config:Config; entries:Memory[]; automatic_today:number; last_recall:null|{query:string;items:Score[];at:number} }
const initial:Config={enabled:true,auto_extract:true,half_life_days:30,max_recall:6,relevance_threshold:0.18,daily_auto_limit:8}
const { data, loading, error, load } = useResource(() => api<Data>('/memory/state'), {config:initial,entries:[],automatic_today:0,last_recall:null} as Data)
const draft=reactive({...initial}), archived=ref(false), query=ref(''), preview=ref<Score[]|null>(null), saving=ref(false)
watch(()=>data.value.config,c=>Object.assign(draft,c))
const visible=computed(()=>data.value.entries.filter(m=>archived.value||m.status==='active'))
const explanations=computed(()=>preview.value??data.value.last_recall?.items??[])
function add() { openForm({title:'让灵犀记住一件事',description:'稳定的偏好可以长期保留，一段近况可以慢慢淡化。',fields:[field('content','要记住什么','','textarea',true),choice('importance','重要程度',[['1','1 · 次要'],['2','2 · 一般'],['3','3 · 普通'],['4','4 · 重要'],['5','5 · 非常重要']],3),choice('memory_type','如何保留',[['fact','长期事实 · 不淡忘'],['episode','近期经历 · 随时间淡化']],'fact'),field('semantic_key','同一事实的标记（可选，例如：我的饮品偏好）',''),field('expires','有效期（留空则不设到期时间）','','datetime-local')],save:async v=>{await post('/memories',{content:v.content,importance:Number(v.importance),memory_type:v.memory_type,semantic_key:v.semantic_key||'',expires_at:v.expires?Math.floor(new Date(v.expires).getTime()/1000):null});notify('灵犀记住了');await load()}}) }
function forget(m:Memory){confirmAction('忘记这条记忆？','自动整理不会再次添加相同的记忆；你仍可以手动重新添加。',async()=>{await remove(`/memories/${m.id}`);await load();preview.value=null;notify('已忘记这条记忆')})}
async function consolidate(){await post('/jobs',{action:'consolidate',params:{},request_id:requestId()});notify('记忆整理已提交，可在任务中心查看')}
async function change(m:Memory,reinforce=false){await patch(`/memories/${m.id}`,reinforce?{reinforce:true}:{memory_type:m.memory_type==='fact'?'episode':'fact'});await load();preview.value=null;notify(reinforce?'已重新唤起这段记忆':'保留方式已更新')}
async function save(){saving.value=true;try{await put('/memory/settings',draft);await load();notify('记忆设置已保存')}finally{saving.value=false}}
async function inspect(){preview.value=await api<Score[]>(`/memory/preview?q=${encodeURIComponent(query.value)}`)}
</script>
<template>
  <PageHeading title="那些值得记住的事" description="重要的约定留在心里，日常的片段随时间慢慢淡化。" eyebrow="A LITTLE MORE UNDERSTANDING"><button class="button secondary" @click="run(consolidate)"><Sparkles :size="16" />整理记忆</button><button class="button" @click="add"><Plus :size="17" />添加记忆</button></PageHeading>
  <div class="memory-banner"><span class="memory-banner-icon"><Brain :size="28" /></span><div><h3>会淡忘，也会重新想起。</h3><p>只有与当下有关的记忆才参与对话。淡忘会影响想起的先后，记录仍然保留。</p></div><span class="memory-count">{{ data.entries.filter(m=>m.status==='active').length }}<small>条记忆</small></span></div>
  <ResourceState :loading="loading" :error="error" @retry="load">
    <details class="panel memory-options"><summary>记忆的节奏与边界</summary><form @submit.prevent="run(save)"><div class="memory-checks"><label><input type="checkbox" v-model="draft.enabled" />按话题相关性与鲜活度召回</label><label><input type="checkbox" v-model="draft.auto_extract" />每 6 次成功对话自动整理一次</label></div><p class="muted">没有值得记住的变化，可以什么都不添。自动整理受长期记忆权限约束；今天新增 {{data.automatic_today}} 条。群人物记忆沿用淡忘参数，数据独立保存。</p><div class="memory-fields"><label>淡忘半衰期（天）<input v-model.number="draft.half_life_days" type="number" min="1" max="365" required /></label><label>每次最多想起几条<input v-model.number="draft.max_recall" type="number" min="1" max="20" required /></label><label>相关性门槛<input v-model.number="draft.relevance_threshold" type="number" min="0.05" max="1" step="0.01" required /></label><label>每天最多自动新增<input v-model.number="draft.daily_auto_limit" type="number" min="0" max="100" required /></label></div><p class="muted">重要的经历淡化更慢，长期事实不淡化。关闭排序后按重要度召回；单独设置的到期时间仍然有效。</p><button class="button" :disabled="saving">保存记忆设置</button></form></details>
    <details class="panel memory-options"><summary>为什么会想起这些</summary><p v-if="data.last_recall" class="muted">最近一次：{{data.last_recall.query}} · {{date(data.last_recall.at)}}</p><form class="inline-actions" @submit.prevent="run(inspect)"><input v-model="query" aria-label="试着检索记忆" placeholder="输入一个话题，看看会想到什么" maxlength="1000" required /><button class="button secondary">预览召回</button><button v-if="preview" type="button" class="text-link" @click="preview=null">查看实际召回</button></form><p class="muted">预览只计算匹配结果，不调用模型，也不刷新记忆。{{preview?'当前显示预览结果，实际回复还会受条数与上下文预算限制。':''}}</p><p v-if="!explanations.length" class="muted">还没有召回记录。</p><article v-for="s in explanations.slice(0,12)" :key="s.id" class="recall-item"><p>{{s.content}}</p><small>{{!preview?(s.selected?'本轮已使用 · ':'本轮未使用 · '):''}}{{s.reason}} · 鲜活度 {{Math.round(s.freshness*100)}}%</small></article></details>
    <div class="list-toolbar"><label><input type="checkbox" v-model="archived" /> 显示到期与被更新的旧版本</label><button class="text-link" @click="load">刷新</button></div>
    <EmptyState v-if="!visible.length" title="从一个小小的偏好开始" description="比如：我喜欢简洁的回答，或者周末喜欢去徒步。"><button class="button secondary" @click="add">添加第一条记忆</button></EmptyState>
    <div v-else class="record-grid"><article v-for="m in visible" :key="m.id" :class="['memory-card',{archived:m.status!=='active'}]"><div class="record-meta"><span :class="['tag',m.memory_type==='fact'?'green':'lilac']"><Pin v-if="m.memory_type==='fact'" :size="12" /><Sparkles v-else :size="12" />{{m.memory_type==='fact'?'长期事实':'近期经历'}}</span><span class="importance" :aria-label="'重要度 '+m.importance+' / 5'"><i v-for="n in 5" :key="n" :class="{filled:n<=m.importance}"></i></span></div><p>{{m.content}}</p><div class="freshness"><span :style="{width:Math.round(m.freshness*100)+'%'}"></span></div><small class="muted">{{m.status==='superseded'?'已被新版本更新':m.status==='expired'?'已到期':`鲜活度 ${Math.round(m.freshness*100)}%`}} · 已想起 {{m.recall_count}} 次 · {{m.source==='manual'?'手动记录':'对话整理'}}</small><small v-if="m.semantic_key" class="memory-key">事实标记：{{m.semantic_key}}</small><div class="memory-footer"><small><Clock3 :size="12" />{{m.expires_at?'有效至 '+date(m.expires_at):date(m.created_at)}}</small><button class="icon-button danger" aria-label="忘记这条记忆" @click="forget(m)"><Trash2 :size="16" /></button></div><div v-if="m.status==='active'" class="inline-actions"><button class="text-link" @click="run(()=>change(m))">{{m.memory_type==='fact'?'允许慢慢淡忘':'设为长期事实'}}</button><button v-if="m.memory_type==='episode'" class="text-link" @click="run(()=>change(m,true))">重新唤起</button></div></article></div>
  </ResourceState>
</template>
<style scoped>
.memory-options{margin-bottom:16px}.memory-options summary{font-weight:650;cursor:pointer}.memory-options form{margin-top:16px}.memory-checks{display:flex;gap:20px;flex-wrap:wrap}.memory-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:16px}.memory-fields label{display:grid;gap:8px;font-size:13px}.memory-fields input,.memory-options .inline-actions input{padding:10px 12px;border:1px solid #ddd1e9;border-radius:10px;background:#fff;min-width:0}.memory-options .inline-actions{flex-wrap:wrap}.memory-options .inline-actions input{flex:1}.recall-item{padding:12px 0;border-bottom:1px solid #f0dfea}.recall-item p{margin:0 0 5px}.recall-item small,.memory-key{color:#746a7c}.memory-key{display:block;margin-top:8px;font-size:12px}.freshness{height:4px;background:#f0dfea;border-radius:8px;margin-bottom:10px;overflow:hidden}.freshness span{display:block;height:100%;background:linear-gradient(90deg,#a4b5d5,#eabcdd)}.archived{opacity:.65}.memory-card .inline-actions{gap:16px}
</style>
